#define _POSIX_C_SOURCE 199309L
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>

// Minimal demonstration of synchronous timed signal wait
int main(void) {
    sigset_t set;
    siginfo_t info;
    struct timespec timeout;
    int sig_num;
    pid_t pid;

    // 1. Define the signal set to wait for (SIGUSR1)
    sigemptyset(&set);
    sigaddset(&set, SIGUSR1);

    // 2. Block the signal globally so sigtimedwait can catch it
    if (pthread_sigmask(SIG_BLOCK, &set, NULL) != 0) {
        perror("pthread_sigmask");
        return EXIT_FAILURE;
    }

    // 3. Set a timeout of 5 seconds
    timeout.tv_sec = 5;
    timeout.tv_nsec = 0;

    printf("Process %d waiting for SIGUSR1 for up to %ld seconds.\n", getpid(), timeout.tv_sec);

    // 4. Create a child process to send the signal to the parent
    pid = fork();

    if (pid == -1) {
        perror("fork");
        return EXIT_FAILURE;
    } else if (pid == 0) {
        // Child process: Sleep, then send signal to parent
        sleep(1);
        if (kill(getppid(), SIGUSR1) == -1) {
            perror("kill");
        }
        printf("Child sent SIGUSR1 to parent and exiting.\n");
        _exit(EXIT_SUCCESS);
    }

    // 5. Parent process calls sigtimedwait
    sig_num = sigtimedwait(&set, &info, &timeout);

    if (sig_num == -1) {
        if (errno == EAGAIN) {
            printf("Timeout reached. No signal received within %ld seconds.\n", timeout.tv_sec);
            return EXIT_SUCCESS;
        } else {
            perror("sigtimedwait error");
            return EXIT_FAILURE;
        }
    } else {
        printf("Signal %d received successfully.\n", sig_num);
        printf("Signal sender PID: %d\n", info.si_pid);
    }

    // Wait for child cleanup
    wait(NULL);

    return EXIT_SUCCESS;
}
